    11→
    12→const apiClient: AxiosInstance = axios.create({
    13→  baseURL: API_URL,
    14→  timeout: API_TIMEOUT,
    15→  headers: {
    16→    'Content-Type': 'application/json',
    17→  },
    18→});
    19→
    20→// Cache session in memory to avoid repeated getSession() calls
    21→let cachedSession: any = null;
    22→
    23→// Initialize session cache immediately
    24→(async () => {
    25→  try {
    26→    const { data: { session } } = await supabase.auth.getSession();
    27→    cachedSession = session;
    28→    console.log('[apiClient] Initial session loaded:', session ? 'Has token' : 'No session');
    29→  } catch (error) {
    30→    console.error('[apiClient] Error loading initial session:', error);
    31→  }
    32→})();
    33→
    34→// Update cache when auth state changes
    35→supabase.auth.onAuthStateChange((_event, session) => {
    36→  console.log('[apiClient] Auth state changed:', _event, session ? 'Has token' : 'No session');
    37→  cachedSession = session;
    38→});
    39→
    40→// Request interceptor - synchronous, just add token
    41→apiClient.interceptors.request.use(
    42→  (config) => {
    43→    // Use cached session (synchronous)
    44→    if (cachedSession?.access_token) {
    45→      config.headers.Authorization = `Bearer ${cachedSession.access_token}`;
    46→    }
    47→    return config;
    48→  },
    49→  (error) => {
    50→    return Promise.reject(error);
    51→  }
    52→);
    53→
    54→// Response interceptor - handle token expiration
    55→apiClient.interceptors.response.use(
    56→  (response) => response,
    57→  async (error: AxiosError) => {
    58→    const originalRequest = error.config as any;
    59→
    60→    if (error.response) {
    61→      // Handle specific error codes
    62→      switch (error.response.status) {
    63→        case 401:
    64→          // If this is the first 401 and we haven't retried yet
    65→          if (!originalRequest._retry) {
    66→            originalRequest._retry = true;
    67→            console.log('[apiClient] 401 error, attempting to refresh session and retry...');
    68→
    69→            try {
    70→              // Force refresh session
    71→              const { data: { session }, error: refreshError } = await supabase.auth.refreshSession();
    72→
    73→              if (refreshError || !session) {
    74→                console.error('[apiClient] Session refresh failed, signing out');
    75→                await supabase.auth.signOut();
    76→                window.location.href = '/login';
    77→                return Promise.reject(error);
    78→              }
    79→
    80→              // Update cached session
    81→              cachedSession = session;
    82→              console.log('[apiClient] Session refreshed, retrying request');
    83→
    84→              // Retry original request with new token
    85→              originalRequest.headers.Authorization = `Bearer ${session.access_token}`;
    86→              return apiClient(originalRequest);
    87→            } catch (refreshError) {
    88→              console.error('[apiClient] Error refreshing session:', refreshError);
    89→              await supabase.auth.signOut();
    90→              window.location.href = '/login';
    91→              return Promise.reject(error);
    92→            }
    93→          } else {
    94→            // Already retried, sign out
    95→            console.error('[apiClient] 401 after retry, signing out');
    96→            await supabase.auth.signOut();
    97→            window.location.href = '/login';
    98→          }
    99→          break;
   100→        case 403:
   101→          console.error('Access forbidden');
   102→          break;
   103→        case 500:
   104→          console.error('Server error');
   105→          break;
   106→      }
   107→    }
